.darma-loader-tw-dot-ring { position: relative; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-dot-ring span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size, 64px) * .15); height: calc(var(--loader-size, 64px) * .15); margin: calc(var(--loader-size, 64px) * -.075) 0 0 calc(var(--loader-size, 64px) * -.075); border-radius: 9999px; background: var(--loader-color, #f59e0b); animation: darma-loader-tw-dot-ring-twDotFade calc(var(--loader-speed, 1s) * 1.2) linear infinite; }
.darma-loader-tw-dot-ring span:nth-child(1) { transform: rotate(0deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.15); }
.darma-loader-tw-dot-ring span:nth-child(2) { transform: rotate(45deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.3); }
.darma-loader-tw-dot-ring span:nth-child(3) { transform: rotate(90deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.45); }
.darma-loader-tw-dot-ring span:nth-child(4) { transform: rotate(135deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-tw-dot-ring span:nth-child(5) { transform: rotate(180deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.75); }
.darma-loader-tw-dot-ring span:nth-child(6) { transform: rotate(225deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -.9); }
.darma-loader-tw-dot-ring span:nth-child(7) { transform: rotate(270deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -1.05); }
.darma-loader-tw-dot-ring span:nth-child(8) { transform: rotate(315deg) translateY(calc(var(--loader-size, 64px) * -.38)); animation-delay: calc(var(--loader-speed, 1s) * -1.2); }
@keyframes darma-loader-tw-dot-ring-twDotFade { 0% { opacity: 1; } 100% { opacity: .12; } }

