{/* keyframes twDotFade: opacity 1 -> .12; place each dot with rotate(n*45deg) translateY(-24px) */}
<div className="relative h-16 w-16">
  {[0, 45, 90, 135, 180, 225, 270, 315].map((angle, index) => (
    <span
      key={angle}
      className="absolute left-1/2 top-1/2 h-2.5 w-2.5 animate-[twDotFade_1.2s_linear_infinite] rounded-full bg-amber-500"
      style={{ margin: "-5px 0 0 -5px", transform: "rotate(" + angle + "deg) translateY(-24px)", animationDelay: -150 * (index + 1) + "ms" }}
    />
  ))}
</div>
